# Generated by manage.py generate_test_cases.
from functools import partial
from typing import Any

from django.core.exceptions import ValidationError
from django.db.models import ProtectedError

from bloomerp.models.document_signing.signature_artifact import SignatureArtifact
from bloomerp.tests.base import (
    BloomerpModelTestCase,
    ExpectedModelException,
    ModelScenario,
)

from .support import SigningFixturesMixin


class TestSignatureArtifactModel(SigningFixturesMixin, BloomerpModelTestCase):
    """Cover immutable evidence file references and protected retention."""

    model = SignatureArtifact

    def artifact_args(self, **overrides: Any) -> dict[str, Any]:
        """Build a file-backed audit report retained with the current request."""
        return {
            "request": self.request,
            "file": self.output,
            "kind": SignatureArtifact.Kind.AUDIT_REPORT,
            "sha256": self.digest,
            **overrides,
        }

    def foreign_recipient_args(self) -> dict[str, Any]:
        """Attempt to attach evidence to a signer of another document."""
        return self.artifact_args(recipient=self.other_request_recipient())

    def get_test_scenarios(self) -> list[ModelScenario[SignatureArtifact]]:
        """Validate evidence ownership, digests, file shape, and append-only storage."""
        return [
            ModelScenario(
                name="Retain an audit report", create_args=self.artifact_args
            ),
            ModelScenario(
                name="Retain signer-specific evidence",
                create_args=partial(self.artifact_args, recipient=self.recipient),
            ),
            ModelScenario(
                name="Reject evidence for another request's recipient",
                create_args=self.foreign_recipient_args,
                expected_exceptions=[ExpectedModelException("create", ValidationError)],
            ),
            ModelScenario(
                name="Reject folders as evidence files",
                create_args=partial(self.artifact_args, file=self.folder),
                expected_exceptions=[ExpectedModelException("create", ValidationError)],
            ),
            ModelScenario(
                name="Reject malformed evidence digests",
                create_args=partial(self.artifact_args, sha256="invalid"),
                expected_exceptions=[ExpectedModelException("create", ValidationError)],
            ),
            ModelScenario(
                name="Reject evidence file replacement",
                create_args=self.artifact_args,
                update_args={"file": self.original},
                expected_exceptions=[ExpectedModelException("update", ValidationError)],
            ),
            ModelScenario(
                name="Retain evidence references",
                create_args=self.artifact_args,
                expected_exceptions=[ExpectedModelException("delete", ValidationError)],
            ),
        ]

    def test_evidence_protects_its_file_and_request(self) -> None:
        """Prevent cascading cleanup from removing a request or file used as evidence."""
        SignatureArtifact.objects.create(**self.artifact_args())
        with self.assertRaises(ProtectedError):
            self.output.delete()
        with self.assertRaises(ProtectedError):
            self.request.delete()
